head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.gLastJob = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        scwin.hideDebugCtrls();

        // fn_SetCode();
        await scwin.initPage();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS21401.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_MASTER_OnLoadError
 * @description dts_MASTER 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_MASTER_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_MASTER);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS21401.dts_MASTER_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_MASTER_OnLoadCompleted
 * @description dts_MASTER 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_MASTER_OnLoadCompleted = function(rowcount) {
    try {
        // 한글금액표기
        txb_AmtHan.setValue(fn_ChgAmtToHan(edt_STD_CD_GRNT_FEE_PACK_PAY_AMT.getValue()));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDINS21401.dts_MASTER_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        let msg = $c.stf.getMessageParam("MSG-A002", scwin.gLastJob);
        await $c.win.alert(msg);
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS21401.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        let msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
        await $c.win.alert(msg);
        const fr_fn_Search = $c.frame.path("../").fn_listGrntFeeApproval;
        fr_fn_Search();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS21401.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Approv_onclick
 * @description 「승인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Approv_onclick = async function() {
    try {
        await scwin.executeGrntFeeApproval("Y");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS21401.btn_Approv_onclick" });
    }
};

/**
 * @method
 * @name btn_REJECT_onclick
 * @description 「거부」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_REJECT_onclick = async function() {
    try {
        await scwin.executeGrntFeeApproval("N");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS21401.btn_REJECT_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDINS21401.btn_Close_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name readGrntFee
 * @description read Grnt Fee 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readGrntFee = async function() {
    const vTemp = frame.FrameID;
    const vROW = vTemp.split("=")[1];

    // alert("vROW : "+vROW);
    /*
    txb_ISUR_CD.value =  frame.Provider("../").dts_PassList.NameValue(vROW,"ISUR_CD");
    txb_COM_NM.value =  frame.Provider("../").dts_PassList.NameValue(vROW,"COM_NM");
    edt_APPL_DDTM.text =  frame.Provider("../").dts_PassList.NameValue(vROW,"APPL_DDTM");
    txb_STD_CD_APCT_ID.value =  frame.Provider("../").dts_PassList.NameValue(vROW,"STD_CD_APCT_ID");
    edt_STD_CD_GRNT_FEE_PACK_PAY_AMT.text =  frame.Provider("../").dts_PassList.NameValue(vROW,"STD_CD_GRNT_FEE_PACK_PAY_AMT");
    txb_CORP_USR_NM.value =  frame.Provider("../").dts_PassList.NameValue(vROW,"CORP_USR_NM");
    txb_BELNG_DEP_NM.value =  frame.Provider("../").dts_PassList.NameValue(vROW,"USR_BELNG_DEP_NM");
    txb_JOBTITL_NM.value =  frame.Provider("../").dts_PassList.NameValue(vROW,"JOBTITL_NM");
    txb_CELLPHONE_NO.value =  frame.Provider("../").dts_PassList.NameValue(vROW,"CELLPHONE_NO");
    txb_TEL_NO.value =  frame.Provider("../").dts_PassList.NameValue(vROW,"TEL_NO");
    txb_EMAIL.value =  frame.Provider("../").dts_PassList.NameValue(vROW,"EMAIL");
    txr_eject_rsn.text =  frame.Provider("../").dts_PassList.NameValue(vROW,"APPL_RSLT_PROCS_CONTN");
     */
    // 납부공문요청일련번호-PK
    txb_PAY_OFCDOC_REQ_SEQ.setValue($c.frame.path("../").dts_PassList.getCellData(vROW, "PAY_OFCDOC_REQ_SEQ"));

    // alert("납부공문요청일련번호 : "+getObjectValue(txb_PAY_OFCDOC_REQ_SEQ));

    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name executeGrntFeeApproval
 * @description execute Grnt Fee Approval 처리
 * @param {*} APPL_FLAG APPL_FLAG
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.executeGrntFeeApproval = async function(APPL_FLAG) {
    if (APPL_FLAG === "Y") {
        scwin.gLastJob = "승인";
    } else if (APPL_FLAG === "N") {
        if (txa_reject_rsn.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "거부사유"));
            txa_reject_rsn.focus();
            return;
        }
        const vRejectRsn = txa_reject_rsn.getValue();
        if ($c.stf.checkMaxLength(txa_reject_rsn, 200, '거부사유') === false) {
            return;
        }
        scwin.gLastJob = "거부";
    }
    txb_APPL_RSLT_CD.setValue(APPL_FLAG);
    //    return;
    let msg = $c.stf.getMessageParam("MSG-A006", scwin.gLastJob);
    const res = window.confirm(msg);
    if (res) {
        trs_Save.KeyName = "toinb_dataid4";
        // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
        // const sbmParams = {
        //     EMP_NO : js_emp_no,
        //     EMP_NM : js_emp_nm,
        //     EMAIL : js_email
        // };
        const sbmOptions = {
            id : "sbm_trs_Save",
            action : "/PrepayInfoAction.do",
            ref : "dts_MASTER",
            target : "trs_Save=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPage
 * @description init Page 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.initPage = async function() {
    await scwin.readGrntFee();
    const vAPPL_RSLT_CD = txb_APPL_RSLT_CD.getValue();
    if (vAPPL_RSLT_CD !== "R") {
        btn_Approv.hide(); // 승인버튼 숨기기.
        btn_REJECT.hide();
        txa_reject_rsn.setReadOnly(true);
    }
    txb_EMP_NO.setValue(js_emp_no); // 세션정보 넘기기.

};

/**
 * @method
 * @name hideDebugCtrls
 * @description hide Debug Ctrls 처리
 * @returns {void}
 * @hidden N
 */
scwin.hideDebugCtrls = function() {
    panel_debug.hide();
};
